def choose_move(observation):
    def clamp(v):
        if v < -1:
            return -1
        if v > 1:
            return 1
        return v

    def first_present(d, keys, default=None):
        for k in keys:
            if isinstance(d, dict) and k in d:
                return d.get(k)
        return default

    def as_pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return (int(x[0]), int(x[1]))
        if isinstance(x, dict):
            xk = first_present(x, ["x", "col", "c", "left"], None)
            yk = first_present(x, ["y", "row", "r", "top"], None)
            if xk is not None and yk is not None:
                return (int(xk), int(yk))
        return None

