        cand = first_present(obs, ["self", "agent", "me", "player"], None)
        if isinstance(cand, dict):
            p = first_present(cand, ["position", "pos", "loc", "location", "xy"], None)
            p2 = as_pos(p)
            if p2 is not None:
                return p2
        p = first_present(obs, ["position", "pos", "loc", "location", "agent_position", "agent_pos", "self_pos"], None)
        p2 = as_pos(p)
        if p2 is not None:
            return p2
        # fallback search in common containers
        for k in ["agents", "players", "units"]:
            arr = obs.get(k, None) if isinstance(obs, dict) else None
            if isinstance(arr, list) and arr:
                for ent in arr:
                    if isinstance(ent, dict) and ent.get("is_self", False):
                        p = as_pos(first_present(ent, ["position", "pos", "loc", "location"], None))
                        if p is not None:
                            return p
        return (0, 0)

    def get_grid(obs):
        for k in ["grid", "map", "board", "terrain", "world"]:
            g = obs.get(k, None) if isinstance(obs, dict) else None
            if g is not None:
                return g
        return None

    def grid_size(grid):
        if isinstance(grid, list) and grid:
            h = len(grid)
            w = len(grid[0]) if isinstance(grid[0], list) else 0
            return (w, h)
        if isinstance(grid, dict):
            w = first_present(grid, ["width", "w", "cols", "x"], None)
            h = first_present(grid, ["height", "h", "rows", "y"], None)
            if w is not None and h is not None:
                return (int(w), int(h))
        return None

    def in_bounds(p, size):
        if size is None:
            return True
        x, y = p
        w, h = size
        return 0 <= x < w and 0 <= y < h

    def blocked(p, grid):
        if grid is None:
            return False
        x, y = p
        if isinstance(grid, list):
            if not grid or y < 0 or y >= len(grid):
                return True
            row = grid[y]
            if not isinstance(row, list) or x < 0 or x >= len(row):
                return True
            cell = row[x]
            if cell in (1, "#", "wall", "W", True):
                return True
            if isinstance(cell, dict):
                return bool(cell.get("blocked", False) or cell.get("wall", False) or cell.get("obstacle", False))
            return False
        return False

    def extract_positions(obs, keys):
        res = []
        for k in keys:
            arr = obs.get(k, None) if isinstance(obs, dict) else None
            if isinstance(arr, list):
                for it in arr:
                    if isinstance(it, dict):
                        p = as_pos(first_present(it, ["position", "pos", "loc", "location", "xy"], it))
                        if p is None:
                            continue
                        if it.get("alive", True) is False:
                            continue
                        res.append((p, it))
                    else:
                        p = as_pos(it)
                        if p is not None:
                            res.append((p, {}))
        return res

