    def nearest_pos(source, items):
        best = None
        best_d = None
        sx, sy = source
        for p, _meta in items:
            d = abs(p[0] - sx) + abs(p[1] - sy)
            if best_d is None or d < best_d:
                best_d = d
                best = p
        return best, best_d

    def score_move(dx, dy):
        nx, ny = me[0] + dx, me[1] + dy
        p = (nx, ny)
        if not in_bounds(p, size) or blocked(p, grid):
            return -10**9

        s = 0.0

        # prefer not to stand still if information is available
        if dx == 0 and dy == 0:
            s -= 0.2

        if resources:
