            if tgt is not None:
                d = abs(tgt[0] - nx) + abs(tgt[1] - ny)
                s += 20 - d * 3
                s += (abs(tgt[0] - me[0]) + abs(tgt[1] - me[1]) - d) * 2

        if enemies:
            # evasion if close, else mild attraction avoidance
            for ep, emeta in enemies:
                d = abs(ep[0] - nx) + abs(ep[1] - ny)
                if d == 0:
                    s -= 50
                elif d == 1:
                    s -= 18
                elif d == 2:
                    s -= 6
                else:
                    s += 0.2

            # if no resources, keep distance from closest enemy
            if mode == "evasion":
                epos, ed = nearest_pos(p, enemies)
                if epos is not None:
                    s += ed * 2

        if territories:
            # move toward first/nearest territory point
            tgt, dist = nearest_pos(p, territories)
            if tgt is not None:
                d = abs(tgt[0] - nx) + abs(tgt[1] - ny)
                s += 8 - d * 1.5

        # center seeking as fallback
        if size is not None:
            cx, cy = size[0] // 2, size[1] // 2
            s += -0.05 * (abs(nx - cx) + abs(ny - cy))

        # slight inertia toward current heading if encoded in observation
        last_move = first_present(observation, ["last_move", "prev_move", "velocity", "direction"], None)
        lm = as_pos(last_move)
        if lm is not None:
            s += 0.1 * (dx == lm[0]) + 0.1 * (dy == lm[1])

        return s

    best = (0, 0)
    best_score = None
    for dx, dy in candidates:
        sc = score_move(dx, dy)
        if best_score is None or sc > best_score:
            best_score = sc
            best = (dx, dy)

    return [clamp(best[0]), clamp(best[1])]

